def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); st = np.asarray(feats.stratum)
    levs = sorted(set(st.tolist()))
    S = np.column_stack([np.ones(n)] + [(st == l).astype(float) for l in levs[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)

    def ll(cols, extra=()):
        Z = np.column_stack([S] + [X[:, j] for j in cols] + list(extra))
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        eta = np.clip(Z @ b, -30, 30)
        return float(np.sum(y * eta - np.logaddexp(0, eta)))

    sel = []; cur = ll(sel)
    gates = [0.05 / p, 0.1 / p, 0.05 / p]
    while len(sel) < MAX_DRIVERS:
        a = gates[min(len(sel), len(gates) - 1)]
        cand = [j for j in range(p) if j not in sel and all(abs(R[j, k]) < 0.6 for k in sel)]
        if not cand: break
        lls = {j: ll(sel + [j]) for j in cand}
        j = max(lls, key=lls.get)
        if stats.chi2.sf(2 * (lls[j] - cur), 1) > a: break
        clus = [k for k in range(p) if k not in sel and (k == j or abs(R[j, k]) >= 0.6)
                and all(abs(R[k, m]) < 0.6 for m in sel)]
        if len(clus) > 1:
            cl = {k: lls[k] if k in lls else ll(sel + [k]) for k in clus}
            best = max(cl.values()); ok = [k for k in clus if cl[k] >= best - 2]
            def rest(k):
                base = cl[k]
                return sum(max(0.0, ll(sel + [k, m]) - base) for m in clus if m != k)
            j = min(ok, key=rest)
        sel.append(j); cur = ll(sel)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            o = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (cur - ll(o)), 1) > 0.05 / p:
                sel = o; cur = ll(sel); changed = True; break
    prods = []
    r = y - y.mean(); v = y.mean() * (1 - y.mean())
    pairs = [(a_, b_) for a_ in range(p) for b_ in range(a_, p)]
    P = np.stack([X[:, a_] * X[:, b_] for a_, b_ in pairs], 1)
    P = (P - P.mean(0)) / (P.std(0) + 1e-9)
    sc = (r @ P) ** 2 / (n * v)
    top = np.argsort(-sc)[:15]; alpha = 0.01 / len(pairs); used = set()
    for t in top:
        a_, b_ = pairs[t]
        if a_ in used or b_ in used or len(prods) >= 2: continue
        mains = sorted(set(sel) | {a_, b_})
        l0 = ll(mains); l1 = ll(mains, [X[:, a_] * X[:, b_]])
        if stats.chi2.sf(2 * (l1 - l0), 1) < alpha:
            prods.append((a_, b_)); used |= {a_, b_}
    drivers = [ids[j] for j in sel]
    for a_, b_ in prods:
        for k in (a_, b_):
            if ids[k] not in drivers: drivers.append(ids[k])
    drivers = drivers[:MAX_DRIVERS]
    cols = sorted(set(sel) | {k for pr in prods for k in pr})
    return Design(drivers=tuple(drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a_], ids[b_]) for a_, b_ in prods), loadings={})

